using Normal.Realtime;

/// Traffic state shared by everyone in a Normcore room. Generated by Normcore's source generator
/// (partial + [RealtimeModel]), like PlayerVenueModel.
[RealtimeModel]
public partial class TrafficSyncModel
{
    // Decides each car's prefab and top speed, so all clients build identical cars.
    [RealtimeProperty(1, true)] private int _seed;
    // Fingerprint of the route list; a mismatch means clients disagree on route indices.
    [RealtimeProperty(2, true)] private int _routeHash;
    // Latest car snapshot (see TrafficNetwork). Unreliable: only the newest value matters.
    [RealtimeProperty(3, false)] private byte[] _state;
}
